/**
 * Public ARIA Executive Briefing endpoint.
 *
 * Returns a structured, bilingual briefing (greeting + system health +
 * pending approvals + proactive priorities) generated by
 * `buildExecutiveBriefing`. Used by the client-side background scanner
 * to keep ARIA proactive without a UI redesign.
 *
 * Public, read-only, per-IP rate-limited, cached edge-side.
 */
import { createFileRoute } from "@tanstack/react-router";
import {
  enforceRateLimit,
  rateLimitResponse,
  rateLimitUnavailableResponse,
} from "@/lib/governance/rate-limit.server";
import { buildExecutiveBriefing } from "@/lib/aria/executive-briefing.server";

function clientIp(req: Request): string {
  const h = req.headers;
  return (
    h.get("cf-connecting-ip") ||
    h.get("x-real-ip") ||
    (h.get("x-forwarded-for") || "").split(",")[0]?.trim() ||
    "anon"
  );
}

export const Route = createFileRoute("/api/public/aria-briefing")({
  server: {
    handlers: {
      GET: async ({ request }) => {
        const ip = clientIp(request);
        const rate = await enforceRateLimit(`pub-aria-briefing:${ip}`, 12, 60);
        if (rate.unavailable) return rateLimitUnavailableResponse();
        if (!rate.allowed) return rateLimitResponse();
        try {
          const briefing = await buildExecutiveBriefing();
          return Response.json(briefing, {
            headers: {
              "Cache-Control": "public, max-age=45, s-maxage=45",
            },
          });
        } catch (e) {
          console.error("[public/aria-briefing]", e instanceof Error ? e.message : e);
          return Response.json({ error: "briefing_failed" }, { status: 502 });
        }
      },
    },
  },
});
